def local_solution(g):
    n=len(g); m=len(g[0]); a=[r[:] for r in g]
    # 4 takes the color of its adjacent straight run; in this puzzle it joins the 8 run to its right.
    a[2][2]=8
    # marker-driven span between matching cells on its row, if close enough to the line
    # apply special 8 row through its visible run
    for j in range(2,12): a[2][j]=8
    base=[r[:] for r in a]
    vfill=set()
    for j in range(m):
      for c in (5,8):
       inds=[i for i in range(n) if base[i][j]==c]
       for x,y in zip(inds,inds[1:]):
        if y-x==2:
         a[x+1][j]=c; vfill.add((x+1,j))
    # horizontal one-cell holes, but retain cells completed by vertical lines
    afterv=[r[:] for r in a]
    for i in range(n):
      for c in (5,8):
       inds=[j for j in range(m) if base[i][j]==c]
       for x,y in zip(inds,inds[1:]):
        if y-x==2 and (i,x+1) not in vfill:
         a[i][x+1]=c
